import { firstBy } from 'thenby'

import { PAGE_SIZE } from '@/lib/pagination'
import {
  getTaskStatusPriorityOfProd,
  getTaskTypePriorityOfProd
} from '@/lib/productions'

// localeCompare(x, undefined, { numeric: true }) builds a new Intl.Collator
// on every call: V8 only caches the collator when no options are passed.
const collator = new Intl.Collator(undefined, { numeric: true })

const sortByEpisode = (a, b) => {
  if (a.episode_name && b.episode_name) {
    return collator.compare(a.episode_name, b.episode_name)
  }
  // The same answer from either side: the rows without an episode go last.
  if (a.episode_name) return -1
  if (b.episode_name) return 1
  return 0
}

const assetComparator = firstBy('canceled')
  .thenBy((a, b) => collator.compare(a.asset_type_name, b.asset_type_name))
  .thenBy('shared')
  .thenBy((a, b) => collator.compare(a.name, b.name))

export const sortAssets = assets => {
  return assets.sort(assetComparator)
}

const shotComparator = firstBy('canceled')
  .thenBy(sortByEpisode)
  .thenBy((a, b) => collator.compare(a.sequence_name, b.sequence_name))
  .thenBy((a, b) => collator.compare(a.name, b.name))

export const sortShots = shots => {
  return shots.sort(shotComparator)
}

const findSortedIndex = (items, item, comparator) => {
  let low = 0
  let high = items.length
  while (low < high) {
    const middle = (low + high) >> 1
    if (comparator(items[middle], item) <= 0) {
      low = middle + 1
    } else {
      high = middle
    }
  }
  return low
}

// Insert one entity into an already-sorted list (binary search) instead of
// re-sorting the whole array on every unit add.
const insertSorted = (items, item, comparator) => {
  items.splice(findSortedIndex(items, item, comparator), 0, item)
  return items
}

// Insert one entity into the rows of a paged list of nbListed entities, and
// return its row. A full page stays full, or an import with the list open
// would render every new entity: the last row goes back to the next page. An
// entity sorted past the rows waits for it too (-1), unless it ends a page
// that is not full.
const insertInPage = (rows, item, comparator, nbListed) => {
  const index = findSortedIndex(rows, item, comparator)
  const isPageFull = rows.length > 0 && rows.length % PAGE_SIZE === 0
  const hasNextPage = nbListed > rows.length + 1
  if (index === rows.length && (isPageFull || hasNextPage)) return -1
  rows.splice(index, 0, item)
  if (isPageFull) rows.pop()
  return index
}

export const insertSortedAsset = (assets, asset) =>
  insertSorted(assets, asset, assetComparator)

export const insertSortedShot = (shots, shot) =>
  insertSorted(shots, shot, shotComparator)

export const insertAssetInPage = (rows, asset, nbListed) =>
  insertInPage(rows, asset, assetComparator, nbListed)

export const insertShotInPage = (rows, shot, nbListed) =>
  insertInPage(rows, shot, shotComparator, nbListed)

export const sortEdits = edits => {
  return edits.sort(
    firstBy('canceled')
      .thenBy(sortByEpisode)
      .thenBy((a, b) => collator.compare(a.name, b.name))
  )
}

export const sortSequences = sequences => {
  return sequences.sort(
    firstBy((a, b) => {
      if (a.episode_name) {
        return collator.compare(a.episode_name, b.episode_name)
      }
      return 0
    }).thenBy((a, b) => {
      return collator.compare(a.name, b.name)
    })
  )
}

export const sortProductions = productions => {
  return productions.sort((a, b) => {
    if (a.project_status_name === b.project_status_name) {
      return collator.compare(a.name, b.name)
    }
    return -1 * collator.compare(a.project_status_name, b.project_status_name)
  })
}

// A task populated before its entity carried a name (a freshly created
// sequence, a raw task from the creation API) has neither entity name.
const getEntityName = task => task.full_entity_name || task.entity_name || ''

const compareByEntityName = (a, b) =>
  collator.compare(getEntityName(a), getEntityName(b))

export const sortTaskNames = (tasks, taskTypeMap) => {
  return tasks.sort(
    firstBy((a, b) => {
      const taskTypeA = taskTypeMap.get(a.task_type_id)
      const taskTypeB = taskTypeMap.get(b.task_type_id)
      return collator.compare(taskTypeA?.name || '', taskTypeB?.name || '')
    }).thenBy(compareByEntityName)
  )
}

export const sortTasks = (tasks, taskTypeMap) => {
  return tasks.sort(
    firstBy('priority', -1)
      .thenBy((a, b) => {
        if (a.project_name) {
          return collator.compare(a.project_name, b.project_name)
        }
        return 0
      })
      .thenBy((a, b) => {
        const taskTypeA = taskTypeMap.get(a.task_type_id)
        const taskTypeB = taskTypeMap.get(b.task_type_id)
        return collator.compare(taskTypeA?.name || '', taskTypeB?.name || '')
      })
      .thenBy(compareByEntityName)
  )
}

export const sortComments = comments => {
  return comments.sort(firstBy('pinned', -1).thenBy('created_at', -1))
}

export const sortRevisionPreviewFiles = previewFiles => {
  return previewFiles.sort(firstBy('position').thenBy('created_at'))
}

export const sortTaskStatuses = (taskStatuses, currentProduction) => {
  return taskStatuses.sort(
    firstBy((taskStatusA, taskStatusB) => {
      const taskStatusAPriority = getTaskStatusPriorityOfProd(
        taskStatusA,
        currentProduction
      )
      const taskStatusBPriority = getTaskStatusPriorityOfProd(
        taskStatusB,
        currentProduction
      )
      return taskStatusAPriority - taskStatusBPriority
    }).thenBy('name')
  )
}

export const sortTaskTypes = (taskTypes, currentProduction) => {
  return [...taskTypes].sort(
    firstBy('for_entity')
      .thenBy((taskTypeA, taskTypeB) => {
        const taskTypeAPriority = getTaskTypePriorityOfProd(
          taskTypeA,
          currentProduction
        )
        const taskTypeBPriority = getTaskTypePriorityOfProd(
          taskTypeB,
          currentProduction
        )
        return taskTypeAPriority - taskTypeBPriority
      })
      .thenBy('name')
  )
}

export const sortTaskTypeScheduleItems = (
  items,
  currentProduction,
  taskTypeMap
) => {
  const priorityCache = new Map()
  for (const item of items) {
    if (!priorityCache.has(item.task_type_id)) {
      const taskType = taskTypeMap.get(item.task_type_id)
      priorityCache.set(
        item.task_type_id,
        getTaskTypePriorityOfProd(taskType, currentProduction)
      )
    }
  }
  const sortFunc = firstBy('for_entity')
    .thenBy((itemA, itemB) => {
      return (
        priorityCache.get(itemA.task_type_id) -
        priorityCache.get(itemB.task_type_id)
      )
    })
    .thenBy('name')
  return items.sort(sortFunc)
}

export const sortPeople = people => {
  return [...people].sort(
    firstBy('active', -1)
      .thenBy((a, b) => (a.first_name || '').localeCompare(b.first_name || ''))
      .thenBy((a, b) => (a.last_name || '').localeCompare(b.last_name || ''))
  )
}

export const sortByName = entries => {
  return entries.sort((a, b) => collator.compare(a.name, b.name))
}

// Sort a list of person ids alphabetically by the person's name. Ids missing
// from a partially loaded personMap sink to the end rather than throwing:
// callers read assignees[0] as "the" assignee, so a hole must never displace a
// person who did resolve.
export const sortByPersonName = (personIds, personMap) => {
  return personIds.sort((a, b) => {
    const nameA = personMap.get(a)?.name
    const nameB = personMap.get(b)?.name
    if (!nameA) return nameB ? 1 : 0
    if (!nameB) return -1
    return nameA.localeCompare(nameB)
  })
}

export const sortByValue = entries => {
  return entries.sort((a, b) => collator.compare(a.value, b.value))
}

export const sortByDate = entries => {
  return entries.sort(firstBy('created_at', -1))
}

export const sortValidationColumns = (
  columns,
  taskTypeMap,
  currentProduction
) => {
  const priorityCache = new Map()
  for (const id of columns) {
    if (!priorityCache.has(id)) {
      priorityCache.set(
        id,
        getTaskTypePriorityOfProd(taskTypeMap.get(id), currentProduction)
      )
    }
  }
  return columns.sort((a, b) => {
    const taskTypeAPriority = priorityCache.get(a)
    const taskTypeBPriority = priorityCache.get(b)
    if (taskTypeAPriority === taskTypeBPriority) {
      const taskTypeA = taskTypeMap.get(a)
      const taskTypeB = taskTypeMap.get(b)
      return collator.compare(taskTypeA?.name || '', taskTypeB?.name || '')
    } else if (taskTypeAPriority > taskTypeBPriority) {
      return 1
    }
    return -1
  })
}

const compareByName = (a, b) => collator.compare(a.name, b.name)

const NUMERIC_FIELDS = new Set(['estimation', 'timeSpent'])

const getFieldValue = (entry, sortInfo, taskTypeMap, episodeMap) => {
  const value = entry[sortInfo.column]
  if (sortInfo.column === 'episode_id') {
    return episodeMap.get(value)?.name || ''
  }
  if (sortInfo.column === 'ready_for') {
    return taskTypeMap.get(value)?.name || ''
  }
  if (sortInfo.column === 'resolution') {
    return entry.data?.resolution || ''
  }
  return value || ''
}

const sortByField = (sortInfo, taskTypeMap, episodeMap) => (a, b) => {
  const dataA = getFieldValue(a, sortInfo, taskTypeMap, episodeMap)
  const dataB = getFieldValue(b, sortInfo, taskTypeMap, episodeMap)
  if (dataA === dataB) return 0
  if (NUMERIC_FIELDS.has(sortInfo.column)) return dataA - dataB
  if (!dataB) return -1
  if (!dataA) return 1
  return collator.compare(String(dataA), String(dataB))
}

// Sorts in place: the arrows of the detail pages walk the cached list in the
// order of its list page.
const sortEntityResult = (
  result,
  sorting,
  taskTypeMap,
  episodeMap,
  taskMap,
  thenBySteps,
  defaultSort
) => {
  if (sorting && sorting.length > 0) {
    const sortInfo = sorting[0]
    const sortEntities =
      sortInfo.type === 'metadata'
        ? sortByMetadata(sortInfo)
        : sortInfo.type === 'field'
          ? sortByField(sortInfo, taskTypeMap, episodeMap)
          : sortByTaskType(taskMap, sortInfo)
    // Descending reverses the whole comparator, so empty values land first
    // instead of last. Special-case empties per direction if that ordering
    // matters.
    const direction = sortInfo.ascending === false ? -1 : 1
    let sorter = firstBy('canceled').thenBy(sortEntities, direction)
    for (const step of thenBySteps) {
      sorter = sorter.thenBy(step)
    }
    result = result.sort(sorter)
  } else {
    result = defaultSort(result)
  }
  return result
}

export const sortAssetResult = (
  result,
  sorting,
  taskTypeMap,
  taskMap,
  episodeMap
) => {
  return sortEntityResult(
    result,
    sorting,
    taskTypeMap,
    episodeMap,
    taskMap,
    [
      (a, b) => collator.compare(a.asset_type_name, b.asset_type_name),
      compareByName
    ],
    sortAssets
  )
}

export const sortShotResult = (result, sorting, taskTypeMap, taskMap) => {
  return sortEntityResult(
    result,
    sorting,
    taskTypeMap,
    new Map(),
    taskMap,
    [
      sortByEpisode,
      (a, b) => collator.compare(a.sequence_name, b.sequence_name),
      compareByName
    ],
    sortShots
  )
}

export const sortSequenceResult = (result, sorting, taskTypeMap, taskMap) => {
  return sortEntityResult(
    result,
    sorting,
    taskTypeMap,
    new Map(),
    taskMap,
    [sortByEpisode, compareByName],
    sortByName
  )
}

export const sortEpisodeResult = (result, sorting, taskTypeMap, taskMap) => {
  return sortEntityResult(
    result,
    sorting,
    taskTypeMap,
    new Map(),
    taskMap,
    [compareByName],
    sortByName
  )
}

export const sortEditResult = (result, sorting, taskTypeMap, taskMap) => {
  return sortEntityResult(
    result,
    sorting,
    taskTypeMap,
    new Map(),
    taskMap,
    [sortByEpisode, compareByName],
    sortEdits
  )
}

// A value written for another type of column ("null" or text from a CSV
// import, "true" left by a boolean one) sorts as an unticked checklist.
const toChecklist = value =>
  value && typeof value === 'object' && !Array.isArray(value) ? value : {}

const parseChecklist = value => {
  if (typeof value !== 'string') return toChecklist(value)
  try {
    return toChecklist(JSON.parse(value))
  } catch {
    return {}
  }
}

// The first items weigh the most. Each cell scores on its own items, so a row
// keeps one score whatever row it meets, even if the column changed since.
const getChecklistScore = checklist => {
  const keys = Object.keys(checklist)
  return keys.reduce(
    (score, key, index) => score + (checklist[key] ? keys.length - index : 0),
    0
  )
}

const getMetadataValues = (sortInfo, a, b, defaultValue = '') => {
  let dataA = a.data?.[sortInfo.column] ?? defaultValue
  let dataB = b.data?.[sortInfo.column] ?? defaultValue

  if (typeof dataA === 'number') dataA = String(dataA)
  if (typeof dataB === 'number') dataB = String(dataB)

  return { dataA, dataB }
}

export const sortByMetadata = sortInfo => {
  if (sortInfo.data_type === 'number') {
    return (a, b) => {
      const { dataA, dataB } = getMetadataValues(sortInfo, a, b)
      if (dataA === dataB) return 0
      if (dataB === '') return -1
      if (dataA === '') return 1
      return collator.compare(dataA, dataB)
    }
  } else if (sortInfo.data_type === 'boolean') {
    return (a, b) => {
      const { dataA, dataB } = getMetadataValues(sortInfo, a, b, 'false')
      // Any value but "true" is unticked, an empty one included.
      const isTickedA = dataA === 'true'
      const isTickedB = dataB === 'true'
      if (isTickedA === isTickedB) return 0
      return isTickedA ? 1 : -1
    }
  } else if (sortInfo.data_type === 'checklist') {
    return (a, b) => {
      const { dataA, dataB } = getMetadataValues(sortInfo, a, b)
      if (dataA === dataB) return 0
      if (!dataB) return -1
      if (!dataA) return 1
      const resultA = getChecklistScore(parseChecklist(dataA))
      const resultB = getChecklistScore(parseChecklist(dataB))
      if (resultA === resultB) return 0
      return resultA < resultB ? 1 : -1
    }
  } else if (sortInfo.data_type === 'taglist') {
    return (a, b) => {
      const { dataA, dataB } = getMetadataValues(sortInfo, a, b)
      if (dataA === dataB) return 0
      if (!dataB) return -1
      if (!dataA) return 1
      return collator.compare(dataA, dataB)
    }
  } else {
    return (a, b) => {
      const { dataA, dataB } = getMetadataValues(sortInfo, a, b)
      if (dataA === dataB) return 0
      if (!dataB) return -1
      if (!dataA) return 1
      return collator.compare(dataA, dataB)
    }
  }
}

const sortByTaskType = (taskMap, sortInfo) => (a, b) => {
  const taskA = a.validations?.get(sortInfo.column)
  const taskB = b.validations?.get(sortInfo.column)
  if (!taskA && !taskB) return 0
  if (!taskA) return -1
  if (!taskB) return 1
  const taskStatusA = taskMap.get(taskA)?.task_status_short_name || ''
  const taskStatusB = taskMap.get(taskB)?.task_status_short_name || ''
  return collator.compare(taskStatusA, taskStatusB)
}
